function candidates( $req ){
		$pet = self::pet( (int)$req['id'] );
		if ( ! $pet ) return new WP_Error('not_found','Augintinis nerastas.',array('status'=>404));
		if ( ! self::species_cat( $pet->species ) ) {
			return rest_ensure_response(array('ok'=>true,'candidates'=>array(),'reason'=>'species_unsupported'));
		}
		$orders = wc_get_orders(array(
			'customer_id' => get_current_user_id(),
			'limit'       => 20,
			'orderby'     => 'date',
			'order'       => 'DESC',
			'status'      => array('wc-processing','wc-completed','wc-on-hold'),
		));
		$seen = array(); $out = array();
		foreach ( (array)$orders as $o ) {
			foreach ( $o->get_items() as $item ) {
				$pid = (int) $item->get_product_id();
				if ( ! $pid || isset($seen[$pid]) ) continue;
				$seen[$pid] = true;
				if ( ! self::is_food_for( $pid, $pet->species ) ) continue;
				$p = wc_get_product( $pid );
				if ( ! $p ) continue;
				$row = self::product_payload( $p );
				$row['last_purchased_at'] = $o->get_date_created() ? $o->get_date_created()->date('Y-m-d') : null;
				$out[] = $row;
				if ( count($out) >= 3 ) break 2;
			}
		}
		return rest_ensure_response(array('ok'=>true,'candidates'=>$out));
	}

	/**
	 * POST /pet-food-assign {pet_id, product_id}
	 * Tik po ai\u0161kaus vartotojo patvirtinimo. -> D busena.
	 */
	public static function assign( $req ){
		$p = $req->get_json_params(); if ( ! is_array($p) ) $p = array();
		$pet = self::pet( isset($p['pet_id']) ? (int)$p['pet_id'] : 0 );
		if ( ! $pet ) return new WP_Error('not_found','Augintinis nerastas.',array('status'=>404));
		$pid = isset($p['product_id']) ? (int)$p['product_id'] : 0;
		$prod = $pid ? wc_get_product( $pid ) : null;
		if ( ! $prod ) return new WP_Error('bad_product','Prekė nerasta.',array('status'=>400));
		if ( ! self::is_food_for( $pid, $pet->species ) ) {
			return new WP_Error('species_mismatch','Ši prekė nėra šio augintinio rūšies maistas.',array('status'=>400));
		}
		global $wpdb; $pf=$wpdb->prefix; $now = current_time('mysql');

		$exists = $wpdb->get_var( $wpdb->prepare(
			"SELECT id FROM {$pf}ps_pet_products WHERE pet_id=%d AND product_id=%d LIMIT 1", $pet->id, $pid ) );
		$data = array(
			'pet_id'=>(int)$pet->id, 'user_id'=>(int)$pet->user_id, 'product_id'=>$pid,
			'sku'=>$prod->get_sku(), 'relationship_type'=>'primary_food',
			'source'=>'user_confirmed', 'confidence'=>1.0, 'updated_at'=>$now,
		);
		if ( $exists ) { $wpdb->update( $pf.'ps_pet_products', $data, array('id'=>$exists) ); }
		else { $data['created_at']=$now; $wpdb->insert( $pf.'ps_pet_products', $data ); }

		// Ankstesnis primary_food -> 'other' (vienas pagrindinis maistas augintiniui)
		$wpdb->query( $wpdb->prepare(
			"UPDATE {$pf}ps_pet_products SET relationship_type='other', updated_at=%s
			 WHERE pet_id=%d AND product_id<>%d AND relationship_type='primary_food'", $now, $pet->id, $pid ) );

		$wpdb->update( $pf.'ps_pets', array(
			'primary_product_id'      => $pid,
			'primary_product_sku'     => $prod->get_sku(),
			'primary_product_name'    => $prod->get_name(),
			'primary_product_package' => $prod->get_attribute('pa_pakuotes_dydis'),
			'updated_at'              => $now,
		), array('id'=>(int)$pet->id) );

		return rest_ensure_response(array('ok'=>true,'state'=>'D','product'=>self::product_payload($prod)));
	}

